class BaseDataset(data.Dataset):
    """Dataset with images from database and queries, used for inference (testing and building cache).
    """
    def __init__(self, img_path):
        super().__init__()
        self.img_path = img_path

        # path to images
        if 'queries' in self.img_path:
            img_path_list = glob.glob(self.img_path + '/*.png', recursive=True)
            self.img_path_list = img_path_list
        elif 'reference_views' in self.img_path:
            img_path_list = glob.glob(self.img_path + '/*.png', recursive=True)
            # sort images for db
            self.img_path_list = sorted(img_path_list, key=lambda x: int(os.path.splitext(os.path.basename(x))[0]))
        else:
            raise ValueError('img_path should be either query or db')
        assert len(self.img_path_list) > 0, f'No images found in {self.img_path}'
    def __getitem__(self, index):
        img = load_image(self.img_path_list[index])
        return img, index
    def __len__(self):
        return len(self.img_path_list)

class ultravpr(nn.Module):
    def __init__(self):
        super().__init__()
        self.backbone = E2ResNet(depth=50, out_indices=(3, ), with_geotensor=True, orientation=8, middle_channels=2048)
        self.aggregator = se2gem(in_dim=256, out_dim=256)
    def forward(self, x):
        x = self.backbone(x)
        x = self.aggregator(x)
        return x

def record_matches(top_k_matches: np.ndarray,
                   query_dataset: BaseDataset,
                   database_dataset: BaseDataset,
                   out_file: str = 'record.txt') -> None:
    with open(f'{out_file}', 'a') as f:
        for query_index, db_indices in enumerate(tqdm(top_k_matches, ncols=100, desc='Recording matches')):
            pred_query_path = query_dataset.img_path_list[query_index]
            for i in db_indices.tolist():
                pred_db_paths = database_dataset.img_path_list[i]
                f.write(f'{pred_query_path} {pred_db_paths}\n')

def calculate_recalls(top_k_matches, query_dataset, database_dataset):
    n_values = [1,5,10]
    top_k = [1,5,10]
    recalls = {}
    for h, j in enumerate(n_values):
        correct_at_n = 0
        for i in range(len(top_k_matches)):
            query_label = re.findall("\d+", query_dataset.img_path_list[i])[-1]
            query_label = int(query_label.lstrip('0'))
            for k in range(j):
                ref_label = re.findall("\d+", database_dataset.img_path_list[top_k_matches[i][k]])[-1]
                ref_label = int(ref_label.lstrip('0'))
                if(abs(query_label-ref_label) <=1):
                    correct_at_n += 1
                    break
        recall_at_n = correct_at_n / len(top_k_matches)
        recalls[j] = recall_at_n
        print("====>Recall@top-{}: {:.4f}".format(top_k[h], recall_at_n))

    return recalls

def __getitem__(self, index):
    img = load_image(self.img_path_list[index])
    return img, index

class BaseDataset(data.Dataset):
    """Dataset with images from database and queries, used for inference (testing and building cache).
    """
    def __init__(self, img_path, img_type):
        super().__init__()
        self.img_path = img_path

        # Validate img_type
        if img_type not in ('query', 'db'):
            raise ValueError('img_type should be either "query" or "db"')

        # path to images
        img_path_list = glob.glob(self.img_path + '/**/**/*.png', recursive=True)

        if img_type == 'query':
            self.img_path_list = img_path_list
        elif img_type == 'db':
            # 过滤只保留编号为0的数据
            self.img_path_list = [x for x in img_path_list if extract_fields(x, 'db')[0] == 0]
            # 排序文件名
            self.img_path_list = sorted(self.img_path_list, key=lambda x: extract_fields(x, 'db'))

        assert len(self.img_path_list) > 0, f'No images found in {self.img_path}'

        file_names_list = [os.path.basename(path) for path in self.img_path_list]

        # Extract coordinates and store them in the same order as img_path_list
        if img_type == 'query':
            self.coordinates = [(longitude, latitude) for _, longitude, latitude in (extract_fields(x, 'query') for x in file_names_list)]
        elif img_type == 'db':
            self.coordinates = [(longitude, latitude) for _, longitude, latitude in (extract_fields(x, 'db') for x in file_names_list)]

    def __getitem__(self, index):
        img = load_image(self.img_path_list[index])
        return img, index

    def __len__(self):
        return len(self.img_path_list)

class ultravpr(nn.Module):
    def __init__(self):
        super().__init__()
        self.backbone = E2ResNet(depth=50, out_indices=(3, ), with_geotensor=True, orientation=8, middle_channels=2048)
        self.aggregator = se2gem(in_dim=256, out_dim=256)
    def forward(self, x):
        x = self.backbone(x)
        x = self.aggregator(x)
        return x

def __getitem__(self, index):
    img = load_image(self.img_path_list[index])
    return img, index

class ExportedResLayer(nn.Module):
    def __init__(self, layer_dict):
        super().__init__()
        blocks = OrderedDict()
        # Iterate through blocks ('0', '1', '2', ...) in sorted order
        for block_name in sorted(layer_dict.keys(), key=int):
            block_dict = layer_dict[block_name]
            # Intelligently choose the correct wrapper based on the presence of 'conv3'
            if 'conv3' in block_dict:
                block = ExportedBottleneck(block_dict)
            else:
                block = ExportedBasicBlock(block_dict)
            blocks[block_name] = block
        self.blocks = nn.ModuleDict(blocks)

    def forward(self, x):
        # Pass the input sequentially through each block in the layer
        for block_name in self.blocks:
            x = self.blocks[block_name](x)
        return x

class UltraVPR(nn.Module):
    def __init__(self, backbone, aggregator):
        super().__init__()
        self.backbone = backbone
        self.aggregator = aggregator
    def forward(self, x):
        x = self.backbone(x)
        x = self.aggregator(x)
        return x

def __init__(self, layer_dict):
    super().__init__()
    blocks = OrderedDict()
    # Iterate through blocks ('0', '1', '2', ...) in sorted order
    for block_name in sorted(layer_dict.keys(), key=int):
        block_dict = layer_dict[block_name]
        # Intelligently choose the correct wrapper based on the presence of 'conv3'
        if 'conv3' in block_dict:
            block = ExportedBottleneck(block_dict)
        else:
            block = ExportedBasicBlock(block_dict)
        blocks[block_name] = block
    self.blocks = nn.ModuleDict(blocks)

def forward(self, x):
    # Pass the input sequentially through each block in the layer
    for block_name in self.blocks:
        x = self.blocks[block_name](x)
    return x

def __init__(self, exported_dict):
    super().__init__()
    layers = OrderedDict()
    for name, module_dict in exported_dict.items():
        # If the module is a 'layer' (e.g., 'layer1'), wrap it with ExportedResLayer
        if name.startswith('layer'):
            layers[name] = ExportedResLayer(module_dict)
        else: # Otherwise, it's a simple module (Conv2d, ReLU, etc.)
            layers[name] = module_dict
    self.layers = nn.ModuleDict(layers)

    # These attributes must match the original E2ResNet configuration
    self.res_layers_names = ['layer1', 'layer2', 'layer3', 'layer4']
    self.out_indices = (3,)
